add(121,'''import {assert,fs,spawnNode} from '../../shared/lab.mjs';await fs.mkdir('./profiles',{recursive:true});const r=await spawnNode(['--cpu-prof','--cpu-prof-dir=./profiles','work.mjs']);console.log(r.stdout);assert.equal(r.code,0,r.stderr);const profiles=(await fs.readdir('./profiles')).filter(x=>x.endsWith('.cpuprofile'));console.log('Open in DevTools:',profiles.at(-1));assert.ok(profiles.length>0);''','A real CPU profile is generated under this lesson’s profiles directory and can be opened in DevTools.',files={'work.mjs':"import {createHash} from 'node:crypto';const start=performance.now();let digest;for(let i=0;i<20000;i++)digest=createHash('sha256').update('fixture:'+i).digest('hex');console.log({digest,elapsedMs:performance.now()-start});"})
add(122,'''import {assert,spawnNode} from '../../shared/lab.mjs';for(const args of [[],['--leak']]){const r=await spawnNode(['--expose-gc','cache.mjs',...args]);console.log(args.length?'unbounded':'bounded',r.stdout);assert.equal(r.code,0,r.stderr);const rows=r.stdout.trim().split('\\n').map(JSON.parse);assert.equal(rows.at(-1).size,args.length?80000:1000);}''','The unbounded cache retains 80000 entries while the bounded cache retains 1000; heap usage is measured rather than assumed.',files={'cache.mjs':"const cache=new Map(),leak=process.argv.includes('--leak');for(let batch=0;batch<8;batch++){for(let i=0;i<10000;i++){const key=batch*10000+i;cache.set(key,{label:'x'.repeat(100),key});if(!leak&&cache.size>1000)cache.delete(cache.keys().next().value);}global.gc?.();console.log(JSON.stringify({batch,size:cache.size,heapUsed:process.memoryUsage().heapUsed}));}"})
add(123,'''import Fastify from 'fastify';import {pgLab} from '../../shared/postgres.mjs';import assert from 'node:assert/strict';await using db=await pgLab();await db.pool.query("INSERT INTO tasks(title,owner_id,created_at) SELECT 'task '||i,(i%100)::text,now()-i*interval '1 second' FROM generate_series(1,10000)i");const app=Fastify();app.get('/tasks',async()=>(await db.pool.query('SELECT id,created_at FROM tasks WHERE owner_id=$1 ORDER BY created_at DESC LIMIT 50',['42'])).rows);await app.listen({port:0,host:'127.0.0.1'});const query="EXPLAIN (ANALYZE,BUFFERS) SELECT id,created_at FROM tasks WHERE owner_id='42' ORDER BY created_at DESC LIMIT 50";try{for(const phase of ['baseline','indexed']){if(phase==='indexed'){await db.pool.query('CREATE INDEX ON tasks(owner_id,created_at DESC)');await db.pool.query('ANALYZE tasks');}console.log(phase,(await db.pool.query(query)).rows);const samples=[];for(let wave=0;wave<5;wave++)await Promise.all(Array.from({length:10},async()=>{const start=performance.now(),r=await fetch('http://127.0.0.1:'+app.server.address().port+'/tasks');assert.equal(r.status,200);await r.json();samples.push(performance.now()-start);}));samples.sort((a,b)=>a-b);console.log({phase,requests:samples.length,p50ms:samples[Math.floor(samples.length*.5)],p95ms:samples[Math.floor(samples.length*.95)]});}}finally{await app.close();}''','Actual HTTP timings and EXPLAIN ANALYZE plans are measured before and after an index. The lab does not assume the index always wins.',mode='postgres',deps=['fastify','pg'])
write('shared/reliability.mjs', '''
import {setTimeout as delay} from 'node:timers/promises';
export function admission({maxActive=8,maxQueued=32}={}){let active=0,max=0;const queue=[];function submit(work){if(active>=maxActive&&queue.length>=maxQueued)return Promise.reject(Error('OVERLOADED'));return new Promise((resolve,reject)=>{const run=async()=>{active++;max=Math.max(max,active);try{resolve(await work());}catch(e){reject(e);}finally{active--;queue.shift()?.();}};if(active<maxActive)void run();else queue.push(run);});}return{submit,stats:()=>({active,queued:queue.length,maxActive:max})};}
export async function retry(operation,signal,{attempts=4,budgetMs=3000,rng=Math.random,sleep=delay}={}){const deadline=AbortSignal.any([signal,AbortSignal.timeout(budgetMs)]);for(let n=1;n<=attempts;n++){deadline.throwIfAborted();try{return await operation({signal:deadline});}catch(e){deadline.throwIfAborted();if(!e.retryable||n===attempts)throw e;await sleep(rng()*Math.min(1000,100*2**(n-1)),undefined,{signal:deadline});}}}
export function breaker(call,now=Date.now){let failures=0,until=0,probing=false;return async(...args)=>{const recovering=until!==0;if(recovering&&(now()<until||probing))throw Error('OPEN');if(recovering)probing=true;try{const result=await call(...args);failures=0;until=0;return result;}catch(e){if(recovering||++failures>=3)until=now()+1000;throw e;}finally{if(recovering)probing=false;}};}
''')
add(124,'''import {admission} from '../../shared/reliability.mjs';import {assert,delay} from '../../shared/lab.mjs';const gate=admission();const jobs=Array.from({length:40},()=>gate.submit(async()=>{await delay(10);return'done';}));await assert.rejects(gate.submit(async()=>{}),/OVERLOADED/);await Promise.all(jobs);console.log(gate.stats());assert.equal(gate.stats().maxActive,8);assert.equal(gate.stats().queued,0);''','Exactly eight slots run concurrently, 32 wait, and the next submission is rejected. All accepted work drains.')
add(125,'''import {retry} from '../../shared/reliability.mjs';import assert from 'node:assert/strict';let calls=0;const controller=new AbortController();const answer=await retry(async()=>{if(++calls<3)throw Object.assign(Error('transient'),{retryable:true});return42;},controller.signal,{rng:()=>0});assert.equal(answer,42);assert.equal(calls,3);let permanent=0;await assert.rejects(retry(async()=>{permanent++;throw Error('permanent');},controller.signal));assert.equal(permanent,1);controller.abort();await assert.rejects(retry(async()=>{throw Error('must not call');},controller.signal));console.log({answer,calls,permanent,cancelled:true});'''.replace('return42','return 42'),'Transient failures consume three of four attempts; permanent errors do not retry; a pre-aborted caller starts no work.')
add(126,'''import {breaker} from '../../shared/reliability.mjs';import assert from 'node:assert/strict';let now=1,calls=0,healthy=false;const call=breaker(async()=>{calls++;if(!healthy)throw Error('dependency down');return'healthy';},()=>now);for(let i=0;i<3;i++)await assert.rejects(call(),/down/);await assert.rejects(call(),/OPEN/);assert.equal(calls,3);now+=1001;healthy=true;assert.equal(await call(),'healthy');assert.equal(await call(),'healthy');console.log({calls,recovered:true});''','Three failures open the breaker; an open call never reaches the dependency, and a later successful probe closes it.')
add(127,'''import {createServer} from 'node:http';import {Database} from 'node:sqlite';import {assert,listen,close,delay} from '../../shared/lab.mjs';const db=new Database(':memory:');let stopping=false;const timer=setInterval(()=>{},1000);let entered;const started=new Promise(r=>entered=r);const server=createServer(async(q,s)=>{entered();await delay(30);s.end('finished');});const base=await listen(server),request=fetch(base).then(r=>r.text());await started;async function shutdown(){if(stopping)return;stopping=true;clearInterval(timer);await close(server);db.close();}await shutdown();assert.equal(await request,'finished');await shutdown();assert.throws(()=>db.exec('SELECT 1'));console.log('in-flight request drained, producer stopped, database closed, repeated shutdown ignored');''','A real HTTP request drains before a real SQLite connection closes; shutdown is idempotent.')
add(128,'''import {assert,spawnNode} from '../../shared/lab.mjs';import {npm} from '../../shared/npm.mjs';const run=await spawnNode(['native.ts']);console.log('runtime:',run.stdout);assert.equal(run.stdout.trim(),'42');const check=await npm(['exec','--','tsc','--noEmit','--skipLibCheck','--target','ES2022','native.ts']);console.log('checker:',check.stdout);assert.notEqual(check.code,0);''','Native execution strips erasable types and prints 42 despite a static type error; the TypeScript checker rejects it.',files={'native.ts':"function twice(value:number):number{return value*2;}const input:number='21';console.log(twice(input));"},deps=['typescript'])
add(129,'''import {assert,fs,spawnNode} from '../../shared/lab.mjs';import {npm} from '../../shared/npm.mjs';const build=await npm(['exec','--','tsc','-p','tsconfig.json']);assert.equal(build.code,0,build.stdout+build.stderr);const declaration=await fs.readFile('./dist/index.d.ts','utf8');assert.ok(declaration.includes('greet'));const run=await spawnNode(['--input-type=module','--eval',"import {greet} from './dist/index.js';console.log(greet('student'));"]);console.log(run.stdout,declaration);assert.equal(run.stdout.trim(),'Hello, student');''','Compilation emits runnable JavaScript, declarations and source maps; the compiled library returns the greeting.',files={'src/index.ts':"export function greet(name:string):string{return 'Hello, '+name;}",'tsconfig.json':'{"compilerOptions":{"target":"ES2022","module":"NodeNext","moduleResolution":"NodeNext","strict":true,"declaration":true,"sourceMap":true,"outDir":"dist","rootDir":"src","skipLibCheck":true},"include":["src/**/*.ts"]}'},deps=['typescript','@types/node'])
add(130,'''import {assert,spawnNode} from '../../shared/lab.mjs';import {npm} from '../../shared/npm.mjs';for(const file of ['bad.js','fixed.js']){const run=await spawnNode([file]);console.log(file,'runtime',run.stdout.trim());const check=await npm(['exec','--','tsc','--allowJs','--checkJs','--noEmit','--skipLibCheck','--module','NodeNext','--target','ES2022',file]);console.log(check.stdout);assert.equal(check.code,file==='fixed.js'?0:2);}''','JavaScript permits string concatenation at runtime; JSDoc checking detects the bad argument and accepts the fixed call.',files={'bad.js':"/** @param {number} a @param {number} b @returns {number} */\nexport function add(a,b){return a+b;}console.log(add('2',3));",'fixed.js':"/** @param {number} a @param {number} b @returns {number} */\nexport function add(a,b){return a+b;}console.log(add(2,3));"},deps=['typescript'])
add(131,'''import {createRequire} from 'node:module';import assert from 'node:assert/strict';const require=createRequire(import.meta.url);let addon;try{addon=require('./build/Release/addon.node');}catch(cause){throw Error('Build first: npm exec -- node-gyp rebuild --directory lessons/prompt-131',{cause});}console.log(addon.twice(21));assert.equal(addon.twice(21),42);assert.throws(()=>addon.twice('21'),TypeError);''','After native compilation, the addon returns 42 and rejects a nonnumeric argument.','Windows requires Visual Studio C++ Build Tools and Python; macOS requires Xcode CLI tools; Linux requires make and a supported compiler. Node-API ABI stability does not remove OS/architecture constraints.',files={'native.cc':'''#include <napi.h>
Napi::Value Twice(const Napi::CallbackInfo& info){Napi::Env env=info.Env();if(info.Length()!=1||!info[0].IsNumber()){Napi::TypeError::New(env,"Expected one number").ThrowAsJavaScriptException();return env.Undefined();}return Napi::Number::New(env,info[0].As<Napi::Number>().DoubleValue()*2);}
Napi::Object Init(Napi::Env env,Napi::Object exports){exports.Set("twice",Napi::Function::New(env,Twice));return exports;}
NODE_API_MODULE(addon,Init)''','binding.gyp':'''{"targets":[{"target_name":"addon","sources":["native.cc"],"include_dirs":["<!@(node -p \\"require('node-addon-api').include\\")"],"dependencies":["<!(node -p \\"require('node-addon-api').gyp\\")"],"defines":["NAPI_DISABLE_CPP_EXCEPTIONS"]}]}'''.replace('\\"','\"')},mode='native-tooling',deps=['node-addon-api','node-gyp'])
add(132,'''import wabtInit from 'wabt';import assert from 'node:assert/strict';const wabt=await wabtInit(),parsed=wabt.parseWat('double.wat','(module (func (export "double") (param i32) (result i32) local.get 0 i32.const 2 i32.mul))');const {buffer}=parsed.toBinary({});parsed.destroy();const {instance}=await WebAssembly.instantiate(buffer);console.log(instance.exports.double(21),instance.exports.double(2147483647));assert.equal(instance.exports.double(21),42);assert.equal(instance.exports.double(2147483647),-2);''','Compiled WAT executes as WebAssembly; i32 overflow wraps rather than producing the same Number result as unbounded JS.',deps=['wabt'])
add(133,'''import {assert,fs,spawnNode} from '../../shared/lab.mjs';await fs.mkdir('./.compile-cache',{recursive:true});for(const phase of ['cold','warm','disabled']){const start=performance.now();const env={...process.env};if(phase==='disabled')env.NODE_DISABLE_COMPILE_CACHE='1';const r=await spawnNode(['cache.mjs'],{env});console.log({phase,elapsedMs:performance.now()-start,output:r.stdout});assert.equal(r.code,0,r.stderr);assert.ok(r.stdout.includes('42'));}''','Cache status and full-process startup times are measured. Caching does not cache exported business results or guarantee a speedup.',files={'cache.mjs':"import {enableCompileCache} from 'node:module';console.log(JSON.stringify(enableCompileCache('./.compile-cache')));await import('./cli.mjs');",'cli.mjs':"import {answer} from './math.mjs';console.log(answer);",'math.mjs':'export const answer=42;'})
add(134,'''import vm from 'node:vm';import assert from 'node:assert/strict';const scope={count:1};vm.createContext(scope);const script=new vm.Script('count+=2;count');console.log(script.runInContext(scope,{timeout:50}),scope.count,globalThis.count);assert.equal(scope.count,3);assert.equal(globalThis.count,undefined);assert.throws(()=>new vm.Script('while(true){}').runInContext(scope,{timeout:10}));console.log('synchronous execution timeout observed');''','Trusted code uses separate global state and the synchronous infinite-loop fixture times out. vm is not a security boundary.')
add(135,'''import {assert,spawnNode} from '../../shared/lab.mjs';const legacy=await spawnNode(['--pending-deprecation','--trace-deprecation','legacy.mjs']);console.log('legacy stdout:',legacy.stdout,'legacy diagnostics:',legacy.stderr);const modern=await spawnNode(['modern.mjs']);console.log('modern:',modern.stdout);assert.equal(modern.code,0,modern.stderr);assert.equal(modern.stdout.trim(),'hello');''','The actual runtime reports legacy warnings or removal errors; modern code preserves the content without relying on deprecated APIs.',files={'legacy.mjs':"import domain from 'node:domain';const data=new Buffer('hello');const scope=domain.create();scope.run(()=>console.log(data.toString()));",'modern.mjs':"const data=Buffer.from('hello','utf8');try{console.log(data.toString());}catch(e){console.error(e.message);process.exitCode=1;}"})
add(136,'''import {execFileSync} from 'node:child_process';import assert from 'node:assert/strict';const run=args=>execFileSync('docker',args,{encoding:'utf8'}).trim();run(['build','-t','node-course-prompt-136','.']);let id;try{id=run(['run','-d','--rm','--init','-p','127.0.0.1::3000','node-course-prompt-136']);const port=run(['port',id,'3000/tcp']).split(':').at(-1);let response;for(let i=0;i<50;i++){try{response=await fetch('http://127.0.0.1:'+port);break;}catch{await new Promise(r=>setTimeout(r,100));}}assert.equal((await response.json()).ok,true);console.log('non-root container replied on its assigned loopback port');}finally{if(id)run(['stop',id]);}''','The complete two-stage Docker image builds, serves a real request as USER node, and the owned container stops.',files={'server.mjs':"import {createServer} from 'node:http';const server=createServer((q,s)=>{s.setHeader('content-type','application/json');s.end(JSON.stringify({ok:true}));});server.listen(3000,'0.0.0.0');process.on('SIGTERM',()=>server.close());",'Dockerfile':'FROM node:26.13.1-bookworm-slim AS deps\nWORKDIR /app\nCOPY container-package.json package.json\nCOPY container-package-lock.json package-lock.json\nRUN npm ci --omit=dev\nFROM node:26.13.1-bookworm-slim\nWORKDIR /app\nCOPY --from=deps --chown=node:node /app/node_modules ./node_modules\nCOPY --chown=node:node server.mjs ./\nUSER node\nEXPOSE 3000\nCMD ["node","server.mjs"]','container-package.json':'{"name":"course-container","version":"1.0.0","private":true}','container-package-lock.json':'{"name":"course-container","version":"1.0.0","lockfileVersion":3,"requires":true,"packages":{"":{"name":"course-container","version":"1.0.0"}}}', '.dockerignore':'node_modules\n.env*\nobserved-output.txt\n'},mode='docker')
workflow='''name: Practical examples
on: [push, pull_request]
jobs:
  lessons:
    strategy:
      matrix:
        os: [ubuntu-latest, windows-latest, macos-latest]
    runs-on: ${{ matrix.os }}
    defaults:
      run:
        working-directory: practical-examples
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: '26.13.1'
          cache: npm
          cache-dependency-path: practical-examples/package-lock.json
      - run: npm ci
      - run: npm run check
      - run: npm test
      - run: npm run validate
'''
write('../.github/workflows/practical-examples.yml',workflow)
add(137,'''import {readFile} from 'node:fs/promises';import assert from 'node:assert/strict';const workflow=await readFile(new URL('../../../.github/workflows/practical-examples.yml',import.meta.url),'utf8');console.log(workflow);for(const command of ['npm ci','npm run check','npm test','npm run validate'])assert.ok(workflow.includes(command));console.log('Workflow is supplied; remote CI execution is not implied by local inspection.');''','The supplied multi-OS GitHub Actions workflow runs reproducible installation and the real validation commands.','The workflow file is also installed under the repository .github/workflows directory. A remote run only happens after a user-authorized push.',files={'ci.yml':workflow})
save()